import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];

  // Load and clone GLB mesh
  const glb = ctx.glbLoader(config.meshUrl);
  const meshScene = glb.scene.clone();
  group.add(meshScene);

  // Apply scene placement
  const { scenePosition = [0, 0, 0], rotation = [0, 0, 0], scale = [1, 1, 1] } = config;

  group.position.fromArray(scenePosition);
  group.rotation.fromArray(rotation);
  group.scale.fromArray(scale);

  const initialPos = group.position.clone();
  const initialScale = group.scale.clone();

  // Create accent edge wireframe overlay
  const accentEdge = new THREE.Group();
  meshScene.traverse(child => {
    if (child.isMesh && child.geometry) {
      const edgeGeo = new THREE.EdgesGeometry(child.geometry);
      const edgeMat = new THREE.LineBasicMaterial({
        color: 0xff2a38,
        linewidth: 1,
        transparent: true,
        opacity: 0.8
      });
      const edges = new THREE.LineSegments(edgeGeo, edgeMat);
      edges.position.copy(child.position);
      edges.rotation.copy(child.rotation);
      edges.scale.copy(child.scale);
      accentEdge.add(edges);
    }
  });
  group.add(accentEdge);
  accentEdge.visible = false;

  // Event handlers
  const handlers = {
    onHover: () => {
      timelines.forEach(tl => tl.kill());
      timelines.length = 0;

      const tl = gsap.timeline();
      tl.to(group.position, {
        y: initialPos.y + 0.15,
        duration: 0.7,
        ease: 'power3.out'
      });
      timelines.push(tl);
    },

    onHoverEnd: () => {
      timelines.forEach(tl => tl.kill());
      timelines.length = 0;

      const tl = gsap.timeline();
      tl.to(group.position, {
        y: initialPos.y,
        duration: 0.5,
        ease: 'power3.out'
      });
      timelines.push(tl);
    },

    onClick: () => {
      timelines.forEach(tl => tl.kill());
      timelines.length = 0;

      const tl = gsap.timeline();
      tl.to(group.scale, {
        x: initialScale.x * 0.97,
        y: initialScale.y * 0.97,
        z: initialScale.z * 0.97,
        duration: 0.06,
        ease: 'back.out'
      }).to(group.scale, {
        x: initialScale.x,
        y: initialScale.y,
        z: initialScale.z,
        duration: 0.06,
        ease: 'back.out'
      });
      timelines.push(tl);

      // Emit event
      if (config.onEvent) {
        config.onEvent('hub-home.select');
      }
    },

    onFocus: () => {
      accentEdge.visible = true;
    },

    onBlur: () => {
      accentEdge.visible = false;
    }
  };

  group.userData.handlers = handlers;

  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    accentEdge.traverse(child => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
